package com.hailiang.notice.m3e;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.os.*;import android.text.*;import android.text.method.LinkMovementMethod;import android.view.*;import android.widget.*;import java.util.*;import java.util.regex.*;import java.util.concurrent.*;import java.net.*;import java.io.*;

public final class NativeReader {
 private static final ExecutorService workers=Executors.newFixedThreadPool(2);
 private static final Map<Activity,NativeReader> external=new WeakHashMap<Activity,NativeReader>();
 private final Activity a;private final ViewGroup host;private final Ui.Colors p;private final Runnable back;
 private final List<Future<?>> jobs=new ArrayList<Future<?>>();private final List<InlineImage> images=new ArrayList<InlineImage>();private final List<Object> voices=new ArrayList<Object>();private final List<Bitmap> bitmaps=new ArrayList<Bitmap>();
 private boolean disposed;private Object shown;
 public NativeReader(Activity activity,ViewGroup target,Runnable close){a=activity;host=target;back=close;p=new Ui.Colors(a);}
 public void show(final Object item){
  shown=item;
  host.removeAllViews();LinearLayout base=Ui.column(a);base.setPadding(Ui.dp(a,24),Ui.dp(a,16),Ui.dp(a,24),0);
  LinearLayout controls=Ui.row(a);TextView close=Ui.button(a,"返回",false,new View.OnClickListener(){public void onClick(View v){back.run();}});controls.addView(close);View space=new View(a);controls.addView(space,new LinearLayout.LayoutParams(0,1,1));controls.addView(Ui.button(a,"分享",false,new View.OnClickListener(){public void onClick(View v){Intent i=new Intent(Intent.ACTION_SEND);i.setType("text/plain");i.putExtra(Intent.EXTRA_TEXT,Data.str(item,"getTitle")+"\n"+Html.fromHtml(Content.html(Data.str(item,"getContent"))).toString());a.startActivity(Intent.createChooser(i,"分享通知"));}}));base.addView(controls,new LinearLayout.LayoutParams(-1,-2));
  ScrollView scroll=new ScrollView(a);scroll.setFillViewport(true);scroll.setClipToPadding(false);LinearLayout content=Ui.column(a);content.setPadding(0,Ui.dp(a,28),0,Ui.dp(a,28));scroll.addView(content,new ScrollView.LayoutParams(-1,-2));base.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));host.addView(base,new ViewGroup.LayoutParams(-1,-1));
  TextView category=Ui.text(a,"class".equals(Data.str(item,"getNoticeType"))?"班级公告":"通知公告",12,p.primary,true);content.addView(category);
  TextView title=Ui.text(a,Data.str(item,"getTitle"),28,p.ink,true);title.setPadding(0,Ui.dp(a,12),0,Ui.dp(a,14));content.addView(title);
  TextView meta=Ui.text(a,Data.str(item,"getPublisher")+"  ·  "+Data.str(item,"getPublishTime"),13,p.muted,false);content.addView(meta);View divider=new View(a);divider.setBackgroundColor(p.outline);LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(-1,Ui.dp(a,1));dp.topMargin=Ui.dp(a,24);dp.bottomMargin=Ui.dp(a,24);content.addView(divider,dp);
  String body=Content.html(Data.str(item,"getContent"));if(body.isEmpty()){content.addView(Ui.text(a,"这条通知没有文字内容，请查看下面的附件。",16,p.muted,false));}else renderHtml(content,body);
  List<?> files=Data.list(item,"getFileList");if(files.isEmpty())files=Content.files(Data.str(item,"getContent"));if(files.isEmpty()&&"voice".equals(Data.str(item,"getContentType"))&&Content.url(Data.str(item,"getContent")))files=Collections.singletonList(new Content.Attachment("语音通知",Data.str(item,"getContent"),"audio"));if(!files.isEmpty()){TextView h=Ui.text(a,"附件",18,p.ink,true);h.setPadding(0,Ui.dp(a,28),0,Ui.dp(a,12));content.addView(h);for(Object file:files)file(content,file);}
 }
 private void renderHtml(LinearLayout content,String html){Matcher tables=Pattern.compile("(?is)<table\\b[^>]*>.*?</table>").matcher(html);int position=0;while(tables.find()){paragraph(content,html.substring(position,tables.start()));table(content,tables.group());position=tables.end();}paragraph(content,html.substring(position));}
 private void paragraph(LinearLayout content,String html){if(html.trim().isEmpty())return;final TextView t=Ui.text(a,"",18,p.ink,false);t.setLineSpacing(Ui.dp(a,6),1.12f);t.setTextIsSelectable(true);t.setLinksClickable(true);t.setMovementMethod(LinkMovementMethod.getInstance());final List<InlineImage> own=new ArrayList<InlineImage>();
  Spanned value=Html.fromHtml(html,new Html.ImageGetter(){public Drawable getDrawable(String source){InlineImage image=new InlineImage(t,source);own.add(image);images.add(image);return image;}},null);t.setText(value);t.setPadding(0,0,0,Ui.dp(a,12));content.addView(t,new LinearLayout.LayoutParams(-1,-2));
  t.addOnLayoutChangeListener(new View.OnLayoutChangeListener(){public void onLayoutChange(View v,int l,int top,int r,int b,int ol,int ot,int or,int ob){for(InlineImage image:own)image.fit(r-l);}});
 }
 private void table(LinearLayout content,String html){HorizontalScrollView scroll=new HorizontalScrollView(a);TableLayout table=new TableLayout(a);scroll.addView(table,new HorizontalScrollView.LayoutParams(-2,-2));for(String[] cells:Content.table(html)){TableRow row=new TableRow(a);for(String cell:cells){TextView t=Ui.text(a,Html.fromHtml(cell),16,p.ink,false);t.setPadding(Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12));t.setMinWidth(Ui.dp(a,120));t.setBackgroundDrawable(Ui.shape(a,p.container,6));TableRow.LayoutParams lp=new TableRow.LayoutParams(-2,-2);lp.setMargins(Ui.dp(a,2),Ui.dp(a,2),Ui.dp(a,2),Ui.dp(a,2));row.addView(t,lp);}table.addView(row);}content.addView(scroll,new LinearLayout.LayoutParams(-1,-2));}
 private void file(LinearLayout parent,final Object file){final String name=Data.str(file,"getName"),url=Data.str(file,"getUrl"),type=Data.str(file,"getType");LinearLayout box=Ui.column(a);box.setPadding(Ui.dp(a,16),Ui.dp(a,16),Ui.dp(a,16),Ui.dp(a,16));box.setBackgroundDrawable(Ui.shape(a,p.container,20));TextView title=Ui.text(a,name.isEmpty()?"附件":name,16,p.ink,true);box.addView(title);TextView desc=Ui.text(a,type.isEmpty()?"文件":type.toUpperCase(java.util.Locale.ROOT),12,p.muted,false);desc.setPadding(0,Ui.dp(a,6),0,Ui.dp(a,12));box.addView(desc);
  if(type.toLowerCase(java.util.Locale.ROOT).contains("audio")||type.equalsIgnoreCase("voice")||url.matches("(?i).*\\.(mp3|m4a|wav|aac|ogg)(\\?.*)?")){try{Object voice=Class.forName("com.hailiang.notice.voicePlay.VoicePlayer").getConstructor(Context.class).newInstance(a);Object duration=Data.call(file,"getDuration");Data.call(voice,"setAudioUrl",url,duration instanceof Number?((Number)duration).longValue():0L);box.addView((View)voice,new LinearLayout.LayoutParams(-1,Ui.dp(a,52)));voices.add(voice);}catch(Exception ignored){}}
  LinearLayout actions=Ui.row(a);actions.addView(Ui.button(a,"打开",true,new View.OnClickListener(){public void onClick(View v){open(url);}}));TextView download=Ui.button(a,"下载",false,new View.OnClickListener(){public void onClick(View v){download(name,url);}});LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,-2);lp.leftMargin=Ui.dp(a,8);actions.addView(download,lp);box.addView(actions);LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.bottomMargin=Ui.dp(a,12);parent.addView(box,bp);
 }
 private void open(String url){if(!Content.url(url)){Toast.makeText(a,"附件地址无效",Toast.LENGTH_SHORT).show();return;}try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){Toast.makeText(a,"没有可打开此附件的应用，可先下载",Toast.LENGTH_LONG).show();}}
 private void download(String name,String url){if(!Content.url(url)){Toast.makeText(a,"附件地址无效",Toast.LENGTH_SHORT).show();return;}try{DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setTitle(name.isEmpty()?"通知附件":name);r.setDescription("班级通知附件");r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,"班级通知/"+LayoutPolicy.safeName(name));((DownloadManager)a.getSystemService(Context.DOWNLOAD_SERVICE)).enqueue(r);Toast.makeText(a,"已开始下载，可在通知栏查看进度",Toast.LENGTH_LONG).show();}catch(Exception e){Toast.makeText(a,"暂时无法下载，请检查存储权限",Toast.LENGTH_LONG).show();}}
 public void dispose(){disposed=true;for(Future<?> job:jobs)job.cancel(true);for(Object voice:voices)Data.call(voice,"stopPlaying");voices.clear();for(Bitmap bitmap:bitmaps)if(!bitmap.isRecycled())bitmap.recycle();bitmaps.clear();images.clear();}
 public static void start(final Activity a){Ui.inset(a);LinearLayout host=Ui.column(a);host.setBackgroundColor(new Ui.Colors(a).surface);a.setContentView(host);final NativeReader reader=new NativeReader(a,host,new Runnable(){public void run(){a.finish();}});external.put(a,reader);TextView loading=Ui.text(a,"正在读取通知…",20,reader.p.muted,false);loading.setPadding(Ui.dp(a,24),Ui.dp(a,24),Ui.dp(a,24),Ui.dp(a,24));host.addView(loading);final String id=a.getIntent().getStringExtra("noticeId");reader.jobs.add(workers.submit(new Runnable(){public void run(){final Object item=Data.local(id==null?"":id);a.runOnUiThread(new Runnable(){public void run(){if(reader.disposed||a.isFinishing())return;if(item!=null){reader.show(item);Data.read(a,item);}else{reader.host.removeAllViews();TextView message=Ui.text(a,"尚未找到这条通知，请返回列表刷新。",18,reader.p.ink,false);message.setPadding(Ui.dp(a,24),Ui.dp(a,24),Ui.dp(a,24),Ui.dp(a,24));reader.host.addView(message);reader.host.addView(Ui.button(a,"打开通知列表",true,new View.OnClickListener(){public void onClick(View v){try{a.startActivity(new Intent(a,Class.forName("com.hailiang.notice.MainActivity")));a.finish();}catch(Exception ignored){}}}));}}});}}));}
 public static void destroy(Activity a){NativeReader r=external.remove(a);if(r!=null)r.dispose();Data.dispose(a);}
 public static void configuration(Activity a){NativeReader r=external.get(a);if(r==null||r.p.dark==new Ui.Colors(a).dark)return;Object item=r.shown;r.dispose();if(item==null){start(a);return;}NativeReader fresh=new NativeReader(a,r.host,r.back);external.put(a,fresh);r.host.setBackgroundColor(fresh.p.surface);fresh.show(item);}
 private final class InlineImage extends Drawable {
  private final TextView target;private final String url;private Bitmap bitmap;private int maxWidth;
  InlineImage(TextView text,String value){target=text;url=value;maxWidth=Math.max(1,host.getWidth()-Ui.dp(a,48));if(maxWidth<Ui.dp(a,80))maxWidth=Math.max(1,a.getResources().getDisplayMetrics().widthPixels-Ui.dp(a,80));setBounds(0,0,maxWidth,Ui.dp(a,120));
   if(!Content.url(value))return;
   jobs.add(workers.submit(new Runnable(){public void run(){Bitmap result=null;HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(url).openConnection();connection.setConnectTimeout(12000);connection.setReadTimeout(15000);try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(Thread.currentThread().isInterrupted()||out.size()+n>8*1024*1024)throw new IOException("image limit");out.write(buf,0,n);}byte[] bytes=out.toByteArray();BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);options.inSampleSize=1;while(options.outWidth/options.inSampleSize>1600||options.outHeight/options.inSampleSize>2400)options.inSampleSize*=2;options.inJustDecodeBounds=false;result=BitmapFactory.decodeByteArray(bytes,0,bytes.length,options);}}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();}final Bitmap image=result;a.runOnUiThread(new Runnable(){public void run(){if(disposed||a.isFinishing()){if(image!=null)image.recycle();return;}bitmap=image;if(image!=null)bitmaps.add(image);fit(target.getWidth()>0?target.getWidth():maxWidth);target.setText(target.getText());target.requestLayout();target.invalidate();}});}}));
  }
  void fit(int width){if(width<=0||disposed)return;int height=bitmap==null?Ui.dp(a,120):Math.max(1,Math.round((float)width*bitmap.getHeight()/bitmap.getWidth()));if(getBounds().width()!=width||getBounds().height()!=height){maxWidth=width;setBounds(0,0,width,height);target.requestLayout();}}
  public void draw(Canvas canvas){Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);if(bitmap!=null&&!bitmap.isRecycled())canvas.drawBitmap(bitmap,null,getBounds(),paint);else{paint.setColor(p.container);canvas.drawRect(getBounds(),paint);paint.setColor(p.muted);paint.setTextSize(Ui.dp(a,14));canvas.drawText("图片",getBounds().left+Ui.dp(a,16),getBounds().top+Ui.dp(a,30),paint);}}
  public void setAlpha(int alpha){}public void setColorFilter(ColorFilter filter){}public int getOpacity(){return PixelFormat.TRANSLUCENT;}
 }
}
